    ball([head.x+direction*h*.25,head.y-h*.055,head.z+.012],[h*.18,h*.065,h*.095]);
    ball([head.x+direction*h*.22,head.y-h*.13,head.z+.003],[h*.16,h*.033,h*.078]);
