      tube([[head.x-direction*h*.18,head.y+sign*h*.29,head.z-.005],[head.x-direction*h*.07,head.y+sign*h*.39,head.z-.008]],h*.017,8,h*.004);
      tube([[head.x+direction*h*.22,head.y-h*.055,head.z+.02],[head.x+direction*h*.36,head.y+sign*h*.12,head.z+.015],[head.x+direction*h*.24,head.y+sign*h*.23,head.z+.003]],h*.012,14,h*.003);
      for(let k=0;k<3;k++)tube([[head.x-direction*h*.06,head.y,head.z],[head.x-direction*h*(.23+k*.06),head.y+sign*h*(.07+k*.055),head.z+.01],[head.x-direction*h*(.32+k*.055),head.y+sign*h*(.13+k*.065),head.z-.005]],h*.021,12,h*.003);
