// Original-photo reconstruction: dense pierced carving, not a wire halo.
function ref6Leaf(b,x,y,z,w,h,angle=0,material='gold',depth=1) {
  const g=b.geometry('reference6-carved-leaf',()=>{
    const p=[],uv=[],ix=[],rows=10,cols=6,stride=(rows+1)*(cols+1);
    for(let side=0;side<2;side++)for(let j=0;j<=rows;j++)for(let i=0;i<=cols;i++){
      const t=j/rows,u=i/cols*2-1;
      const width=.46*Math.pow(Math.sin(Math.PI*t),.69)*(1+.12*Math.sin(t*Math.PI*8));
      const center=.045*Math.sin(t*Math.PI*1.5),curve=.07*t*t;
      const ridge=.085*Math.sin(Math.PI*t)*(1-u*u)+.018*Math.sin(t*Math.PI*8)*u*u*Math.sin(Math.PI*t);
      p.push(center+u*width,t,curve+(side===0?ridge:-.020));uv.push(i/cols,t);
      if(j<rows&&i<cols){const a=side*stride+j*(cols+1)+i;side===0?ix.push(a,a+1,a+cols+1,a+1,a+cols+2,a+cols+1):ix.push(a,a+cols+1,a+1,a+1,a+cols+1,a+cols+2);}
    }
    closeCarvedShell(ix,rows,cols,stride);const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(ix);g.computeVertexNormals();g.userData.closedCarvedShell=true;g.userData.reference6Reconstruction='carved-lanceolate-leaf';return g;
  });
  b.add(g,material,x,y,z,w,h,depth,0,0,angle);
}
function ref6Scroll(b,x,y,z,w,h,angle=0,material='gold',mirror=1) {
  const g=b.geometry('reference6-foliate-scroll',()=>{
    const pts=[];for(let k=0;k<=24;k++){const t=k/24,a=-Math.PI*.75+t*Math.PI*2.35,r=.40*(1-.78*t);pts.push(new T.Vector3(.08+r*Math.cos(a),.45+r*Math.sin(a),.013*Math.sin(t*Math.PI)));}
    const g=new T.TubeGeometry(new T.CatmullRomCurve3(pts),30,.032,6,false);g.userData.reference6Reconstruction='rolled-scroll';return g;
  });
  // Positive scale keeps winding consistent. Mirror by rotation about Y.
  b.add(g,material,x,y,z,w,h,Math.min(w,h),0,mirror<0?Math.PI:0,angle);
}
function ref6Rosette(b,x,y,z,r,angle=0,material='gold'){
  for(let k=0;k<8;k++){const a=k*Math.PI/4+angle;ref6Leaf(b,x-Math.sin(a)*r*.12,y+Math.cos(a)*r*.12,z,r*.47,r,a,material,.22);}
  b.ball(x,y,z+.017,r*.19,r*.19,.017,material);
}
