function rebuildBannerScrollExterior(original,data) {
  const p=original.attributes.position,n=original.attributes.normal,uv=original.attributes.uv,ix=original.index;
  const removed=new Set(data.remove),positions=[],normals=[],coords=[],indices=[];
  for(let t=0;t<ix.count/3;t++)if(!removed.has(t))for(let k=0;k<3;k++){
    const i=ix.getX(t*3+k);positions.push(p.getX(i),p.getY(i),p.getZ(i));normals.push(n.getX(i),n.getY(i),n.getZ(i));coords.push(uv.getX(i),uv.getY(i));indices.push(indices.length);
  }
  for(let t=0;t<data.f.length;t++){
    const ids=[0,1,2].map(k=>ix.getX(data.f[t]*3+k)),parent=new T.Triangle(...ids.map(i=>new T.Vector3().fromBufferAttribute(p,i)));
    for(let k=0;k<3;k++){
      const point=new T.Vector3().fromArray(data.p,data.i[t*3+k]*3),bary=parent.getBarycoord(point,new T.Vector3()),normal=new T.Vector3(),tex=new T.Vector2();
      for(let j=0;j<3;j++){normal.addScaledVector(new T.Vector3().fromBufferAttribute(n,ids[j]),bary.getComponent(j));tex.addScaledVector(new T.Vector2().fromBufferAttribute(uv,ids[j]),bary.getComponent(j));}
      positions.push(...point.toArray());normals.push(...normal.normalize().toArray());coords.push(tex.x,tex.y);indices.push(indices.length);
    }
  }
  // Keep original/interpolated shading where it remains outward. A folded
  // original corner can point behind the corrected surface, so repair only
  // those corners rather than re-smoothing the entire carved scroll.
  for(let t=0;t<positions.length/9;t++){
    const points=[0,1,2].map(k=>new T.Vector3().fromArray(positions,(t*3+k)*3)),face=points[1].clone().sub(points[0]).cross(points[2].clone().sub(points[0])).normalize();
    for(let k=0;k<3;k++){const i=(t*3+k)*3,normal=new T.Vector3().fromArray(normals,i);if(normal.dot(face)<=1e-6){normals[i]=face.x;normals[i+1]=face.y;normals[i+2]=face.z;}}
  }
  // Share only records whose actual Float32 position, normal and UV all
  // agree exactly. True crease normals stay separate; no geometric welding.
  const pp=[],nn=[],tt=[],ii=[],records=new Map();
  for(let i=0;i<positions.length/3;i++){
    const record=[...positions.slice(i*3,i*3+3),...normals.slice(i*3,i*3+3),...coords.slice(i*2,i*2+2)].map(Math.fround),key=record.map(v=>Object.is(v,-0)?'-0':String(v)).join(',');
    if(!records.has(key)){records.set(key,pp.length/3);pp.push(...record.slice(0,3));nn.push(...record.slice(3,6));tt.push(...record.slice(6,8));}ii.push(records.get(key));
  }
  const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(pp,3));g.setAttribute('normal',new T.Float32BufferAttribute(nn,3));g.setAttribute('uv',new T.Float32BufferAttribute(tt,2));g.setIndex(ii);
  g.userData={...original.userData,regularizedBannerScrollExterior:true,coincidentNormalsSmoothed:true};return g;
}

